parameters.jsCode:
const info = $('DB: Cancelar Cita Cliente').first().json;

const fecha = new Date(info.out_fecha_inicio).toLocaleString('es-CO', {
  weekday: 'long', day: 'numeric', month: 'long',
  hour: 'numeric', minute: '2-digit', hour12: true,
  timeZone: 'America/Bogota'
});

const restantes = Number(info.out_citas_restantes || 0);
const extra = restantes > 0
  ? ` Aún tienes ${restantes} cita(s) más agendada(s); si quieres cancelar otra, dímelo.`
  : '';

return [{
  json: {
    resultado: 'cancelacion_exitosa',
    cancelada: true,
    mensaje_para_cliente: `Listo, ${info.out_cliente_nombre}. Tu cita para ${info.out_servicio_nombre} del ${fecha} ha quedado cancelada exitosamente. El cupo ya fue liberado en la agenda.${extra} Si más adelante deseas agendar de nuevo, me escribes con gusto. ¡Feliz día!`
  }
}];

const r = $input.first().json;
const codigo = r.out_codigo || 'ERROR_TECNICO';

if (codigo === 'ERROR_TECNICO') {
  return [{
    json: {
      resultado: 'cancelacion_no_permitida',
      cancelada: false,
      motivo: codigo,
      mensaje_para_cliente: 'Tuve un inconveniente técnico al intentar cancelar tu cita. Ya le avisé a Andrés para que la cancele contigo directamente.',
      instruccion_agente: 'Fallo técnico. NO digas que la cita fue cancelada. Llama escalar_humano y comunica mensaje_para_cliente.'
    }
  }];
}

if (codigo === 'YA_CANCELADA') {
  return [{
    json: {
      resultado: 'cancelacion_exitosa',
      cancelada: true,
      mensaje_para_cliente: 'Esa cita ya estaba cancelada. No tienes que hacer nada más.'
    }
  }];
}

if (codigo === 'REFERENCIA_REQUERIDA' || codigo === 'NO_ENCONTRADA') {
  return [{
    json: {
      resultado: 'cancelacion_no_permitida',
      cancelada: false,
      motivo: codigo,
      mensaje_para_cliente: 'No encontré ninguna cita activa agendada con tu número para cancelar. Si crees que se trata de un error o reservaste con otro número, avísame y con gusto le dejo una notificación a Andrés.',
      instruccion_agente: 'NO le pidas un código de cita al cliente. Si el cliente insiste en que tiene una cita, llama escalar_humano.'
    }
  }];
}

return [{
  json: {
    resultado: 'cancelacion_no_permitida',
    cancelada: false,
    motivo: codigo,
    mensaje_para_cliente: r.out_mensaje
  }
}];
